def shipWithinDays(weights: list[int], days: int) -> int:
    lo, hi = max(weights), sum(weights)
    ans = hi
    while lo <= hi:
        mid = (lo + hi) // 2
        d_needed = 1
        curr = 0
        for w in weights:
            if curr + w > mid:
                d_needed += 1
                curr = w
            else:
                curr += w
        if d_needed <= days:
            ans = mid
            hi = mid - 1
        else:
            lo = mid + 1
    return ans

